import { useState } from 'react'

/**
 * The no-WebGL / reduced-motion hero art. A still frame of the same wizard, so the
 * fallback reads as a deliberate composition rather than an empty right column.
 * Generated by `npm run shoot:hero` in Task 7.
 *
 * The image does not exist yet (Task 7 generates it from the live 3D scene), so we
 * degrade honestly here: if it 404s, hide the <img> entirely rather than showing a
 * broken-image icon with alt text describing art that isn't there. Once Task 7 lands
 * the asset this becomes a no-op — the image just renders.
 */
export function StaticHeroArt() {
  const [broken, setBroken] = useState(false)

  return (
    <div className="stage stage--static" aria-hidden="false">
      {!broken && (
        <img
          src="/shots/hero-wizard.webp"
          alt="Illustration of a robed wizard holding a lit wand"
          onError={() => setBroken(true)}
        />
      )}
    </div>
  )
}
